pub(crate) const STYLES: &str = r#"
.df-combat{--gold:#d9b77a;--muted:#b4aca0;position:relative;isolation:isolate;min-height:100svh;background:#141310;color:#f4eddf;font:16px/1.5 Georgia,'Times New Roman',serif;overflow:hidden}
.df-combat *{box-sizing:border-box;min-width:0}.df-combat [hidden]{display:none!important}.df-combat p,.df-combat h1,.df-combat h2,.df-combat h3,.df-combat button,.df-combat dd{overflow-wrap:anywhere}.df-combat .combat-art{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 40%;z-index:-3;color:var(--muted)}.df-combat:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#12100a80,transparent 20%,#14131018 40%,#141310e8 76%,#141310),linear-gradient(90deg,#11100db3,transparent 65%)}
.df-combat .combat-topbar{display:flex;align-items:center;gap:22px;padding:22px 4vw;background:linear-gradient(#11100a99,transparent)}.df-combat .combat-brand{font-size:26px;letter-spacing:-1px;color:#efce91}.df-combat .combat-location{flex:1;margin:0;font:10px/1.6 system-ui,sans-serif;text-transform:uppercase;letter-spacing:2.5px;color:#e0d8c8}.df-combat .combat-notice{font:10px/1.5 system-ui,sans-serif;letter-spacing:1.5px;text-transform:uppercase;color:#c7b48f;padding:6px 0 6px 12px;border-left:1px solid #d9b77a66}
.df-combat .combat-stage{width:min(1600px,92%);margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:5vw;align-items:end;min-height:calc(100svh - 350px);padding:150px 0 38px}.df-combat .combat-story{padding:0 0 8px}.df-combat .combat-overline{font:10px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin:0 0 13px}.df-combat h1{font-weight:400;font-size:clamp(46px,5.5vw,86px);line-height:1.04;letter-spacing:-2px;text-shadow:0 3px 35px #000;margin:0 0 20px;max-width:820px}.df-combat .combat-narration{font-size:18px;line-height:1.65;color:#eee5d5;max-width:560px;margin:0;text-shadow:0 2px 8px #000}
.df-combat .combat-initiative{padding:18px 20px;background:linear-gradient(135deg,#24211bee,#181713ee);border:1px solid #c7a86b4d;border-radius:10px;box-shadow:0 16px 45px #0005}.df-combat .combat-actors,.df-combat .combat-rolls{list-style:none;margin:0;padding:0}.df-combat .combat-actor{display:flex;gap:12px;align-items:center;padding:12px 0;border-top:1px solid #d9b77a24}.df-combat .combat-actor:first-child{border-top:0}.df-combat .combat-actor[data-active=true] h3{color:#f4d79e}.df-combat .combat-actor-body{flex:1}.df-combat .combat-initiative-value{min-width:38px;max-width:38%;min-height:38px;padding:8px;overflow-wrap:anywhere;text-align:center;flex:0 1 auto;display:grid;place-items:center;background:#151511;border:1px solid #a394713d;border-radius:50%;color:#c6b995;font:18px/1.1 Georgia,serif}.df-combat .combat-actor[data-active=true] .combat-initiative-value{color:#f3d28b;border-color:#d0a965;box-shadow:0 0 18px #bb853b1f}.df-combat h3{font-weight:400;margin:0;font-size:18px;line-height:1.3}.df-combat .combat-muted{font:11px/1.5 system-ui,sans-serif;color:var(--muted);margin:4px 0 0}.df-combat .combat-resources{display:grid;grid-template-columns:auto 1fr;column-gap:12px;row-gap:3px;margin:7px 0 0;font:11px/1.5 system-ui,sans-serif}.df-combat .combat-resources dt{color:#aaa08b}.df-combat .combat-resources dd{margin:0;color:#e5d6b8;text-align:right}
.df-combat .combat-lower{width:min(1600px,92%);margin:auto;display:grid;grid-template-columns:minmax(0,1.7fr) minmax(240px,1fr);gap:30px;align-items:start;padding:0 0 25px}.df-combat .combat-action-rail{padding:20px 0;border-top:1px solid #d9b77a59}.df-combat .combat-roll-panel{padding:20px 24px;border-left:1px solid #d9b77a59;background:linear-gradient(90deg,#b78c4217,transparent);border-radius:0 8px 8px 0}.df-combat h2{font-weight:400;font-size:23px;line-height:1.3;margin:0 0 17px}.df-combat .combat-offers{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.df-combat .combat-offer{padding:0;background:none;border:0}.df-combat button{width:100%;min-height:48px;border:1px solid #a98b574d;background:#29251e;color:#ede2cb;border-radius:6px;padding:11px 15px;font:13px/1.5 system-ui,sans-serif;cursor:pointer;touch-action:manipulation;box-shadow:inset 0 1px 0 #fff1}.df-combat .combat-offer[data-kind=action] button:enabled{background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;border-color:#e9c78d;font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-combat .combat-offer[data-kind=roll] button:before{content:'◇';margin-right:8px;color:#dcb677}.df-combat button:hover:enabled{background:#42382a;border-color:#e5bd77}.df-combat .combat-offer[data-kind=action] button:hover:enabled{background:#edcea0}.df-combat button:disabled{color:#9c9488;background:#1d1c17;cursor:default;border-color:#8c806b3d;box-shadow:none}.df-combat :focus-visible{outline:3px solid #f1d69b;outline-offset:4px}.df-combat button[aria-busy=true]{border-style:dashed}.df-combat .combat-offer p{margin:7px 2px 0}
.df-combat .combat-reaction{margin-top:17px;padding:13px 16px;border-left:2px solid #c6ad76;background:#b4995812;border-radius:0 6px 6px 0}.df-combat .combat-reaction h3{color:#e8d7b3;font-size:17px}.df-combat .combat-timing{margin:5px 0;color:#ddc28e;font:11px/1.5 system-ui,sans-serif}.df-combat .combat-draft{margin-top:16px}.df-combat .df-ui-field{display:grid;gap:5px}.df-combat .df-ui-field label{display:grid;gap:6px;font:11px/1.6 system-ui,sans-serif;color:#c5b99e}.df-combat input{width:100%;min-height:44px;color:#f4eddf;background:#161510;border:1px solid #a3916b59;border-radius:6px;font:14px/1.5 system-ui,sans-serif;padding:10px 12px}.df-combat input[aria-invalid=true]{border-color:#dfa390}.df-combat .df-ui-feedback,.df-combat .combat-feedback{font:12px/1.6 system-ui,sans-serif;margin:7px 0 0;color:#dcc393}.df-combat .df-ui-feedback:empty,.df-combat .combat-feedback:empty,.df-combat .combat-muted:empty{display:none}.df-combat .combat-feedback[data-state=refused]{color:#f0b9a3}.df-combat .combat-roll{display:grid;grid-template-columns:64px 1fr;column-gap:15px;padding:0 0 15px;margin:0 0 15px;border-bottom:1px solid #b7a48233}.df-combat .combat-roll:last-child{border-bottom:0;margin:0;padding-bottom:0}.df-combat .combat-roll h3{grid-column:2;font:12px/1.5 system-ui,sans-serif;color:#e1d4b9;letter-spacing:.3px}.df-combat .combat-roll-value{grid-column:1;grid-row:1 / span 4;display:grid;place-items:center;align-self:center;aspect-ratio:1;margin:0;border:1px solid #cba46680;clip-path:polygon(25% 0,75% 0,100% 25%,100% 75%,75% 100%,25% 100%,0 75%,0 25%);background:linear-gradient(140deg,#86633340,#171611);font:35px/1 Georgia,serif;color:#f0d091}.df-combat .combat-roll-explanation{grid-column:2;font:12px/1.6 system-ui,sans-serif;color:#d8cbb2;margin:4px 0}.df-combat .combat-roll-source{grid-column:2;font:10px/1.6 system-ui,sans-serif;color:#a99c84;margin:3px 0 0}.df-combat .combat-connection{text-align:center;color:#a89c84;font:10px/1.7 system-ui,sans-serif;padding:0 4vw 16px}.df-combat .combat-fixture-tools{width:min(1600px,92%);margin:0 auto 30px;border-top:1px solid #ad925d55;padding-top:20px}.df-combat .combat-fixture-tools summary{min-height:44px;color:#dfb974;cursor:pointer}.df-combat .combat-fixture-tools nav{display:flex;flex-wrap:wrap;gap:8px}.df-combat .combat-fixture-tools button{width:auto}.df-combat .combat-fixture-status{font:12px/1.6 system-ui,sans-serif;color:#b6bec6}
@media(min-width:1600px){.df-combat .combat-stage{padding-top:240px}.df-combat .combat-lower{gap:50px}.df-combat .combat-initiative{width:280px;justify-self:end}}
@media(max-width:1000px){.df-combat .combat-stage{grid-template-columns:1fr 240px;gap:24px;min-height:500px;padding-top:120px}.df-combat h1{font-size:56px}.df-combat .combat-lower{grid-template-columns:1.3fr 1fr;gap:20px}.df-combat .combat-offers{grid-template-columns:1fr}.df-combat .combat-offer p{margin:4px 2px 0}}
@media(max-width:700px){.df-combat .combat-topbar{padding:17px 5vw 0;gap:6px 14px;flex-wrap:wrap}.df-combat .combat-brand{font-size:22px;flex:1}.df-combat .combat-notice{font-size:8px;letter-spacing:1px;max-width:115px;padding-left:8px}.df-combat .combat-location{order:3;flex-basis:100%;font-size:9px;letter-spacing:2px}.df-combat .combat-art{height:420px;object-position:48% center}.df-combat:before{background:linear-gradient(180deg,#14131050,transparent 19%,#141310b3 32%,#141310 430px)}.df-combat .combat-stage{display:flex;flex-direction:column;align-items:stretch;gap:19px;width:90%;min-height:0;padding:105px 0 18px}.df-combat .combat-story{padding:0}.df-combat .combat-overline{font-size:9px;letter-spacing:2px;margin-bottom:9px}.df-combat h1{font-size:37px;letter-spacing:-1px;max-width:340px;margin-bottom:12px}.df-combat .combat-narration{font-size:14px;line-height:1.6}.df-combat .combat-initiative{padding:13px 15px;border-radius:8px;background:linear-gradient(135deg,#27241ded,#1c1a15ed);box-shadow:0 8px 22px #0002}.df-combat .combat-initiative .combat-overline{margin-bottom:7px}.df-combat .combat-actor{padding:8px 0;gap:11px}.df-combat .combat-actor:first-child{padding-top:0}.df-combat .combat-actor:last-child{padding-bottom:0}.df-combat h3{font-size:17px}.df-combat .combat-initiative-value{min-width:35px;min-height:35px;font-size:17px}.df-combat .combat-resources{margin-top:4px;font-size:10px}.df-combat .combat-lower{width:90%;grid-template-columns:1fr;gap:16px;padding-bottom:16px}.df-combat .combat-action-rail{padding:15px 0 0}.df-combat h2{font-size:21px;margin-bottom:12px}.df-combat .combat-offers{grid-template-columns:1fr 1fr;gap:10px}.df-combat .combat-offer[data-kind=action]{grid-column:1 / -1}.df-combat button{min-height:46px;padding:10px 12px;font-size:12px}.df-combat .combat-offer[data-kind=action] button{font-size:14px}.df-combat .combat-offer p{font-size:10px;line-height:1.4;margin-top:5px}.df-combat .combat-draft{margin-top:13px}.df-combat .combat-roll-panel{padding:14px 16px;border-left:2px solid #cba46673;background:#b78c4212}.df-combat .combat-roll-value{font-size:29px}.df-combat .combat-roll{grid-template-columns:52px 1fr;column-gap:12px}.df-combat .combat-roll-panel h2{font-size:18px}.df-combat .combat-connection{font-size:9px;padding-bottom:13px}.df-combat .combat-fixture-tools{width:90%}.df-combat .combat-fixture-tools nav{display:grid;grid-template-columns:1fr 1fr}.df-combat .combat-fixture-tools button{width:100%;font-size:12px}}
@media(max-width:360px){.df-combat .combat-brand{font-size:20px}.df-combat .combat-notice{max-width:94px;font-size:7px}.df-combat .combat-stage{padding-top:93px}.df-combat h1{font-size:33px}.df-combat .combat-narration{font-size:13px}}
@media(prefers-reduced-motion:reduce){.df-combat *,.df-combat *:before,.df-combat *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
